import { Injectable } from '@angular/core';
import { debounceTime, timer } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class TimerService {
  /**
   * Creates an RxJS timer observable
   */
  timer(dueTime: number) {
    return timer(dueTime);
  }

  /**
   * Creates an RxJS debounceTime operator
   */
  debounceTime(dueTime: number) {
    return debounceTime(dueTime);
  }
} 